package com.example.foliaref;

import io.papermc.paper.threadedregions.scheduler.ScheduledTask;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.concurrent.TimeUnit;

/**
 * Reference: Folia-compatible scheduling for Paper 1.20+ / Folia.
 *
 * KEY RULES:
 *  - Use getServer().getRegionScheduler().run/runDelayed/runAtFixedRate for world-region tasks.
 *  - Use getServer().getAsyncScheduler() for I/O, database, or HTTP work.
 *  - Use getServer().getGlobalRegionScheduler() for non-location tasks on the server thread.
 *  - NEVER use BukkitScheduler (Bukkit.getScheduler()) on Folia — it throws UnsupportedOperationException.
 *  - Always pass `this` (the JavaPlugin) as the first argument to every scheduler call.
 *  - Region tasks must include a Location; they run on the thread owning that region.
 */
public class FoliaSchedulerRef extends JavaPlugin implements Listener {

    @Override
    public void onEnable() {
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent event) {
        Player player = event.getPlayer();
        Location loc  = player.getLocation();

        // --- Region-aware delayed task ---
        // Runs on the region thread owning `loc` after 20 ticks (~1 s).
        // Use this whenever you need to read/write world state near a location.
        getServer().getRegionScheduler().runDelayed(
                this, loc,
                t -> {
                    if (!player.isOnline()) return;
                    player.sendMessage(
                            Component.text("Region task fired 20t after join!", NamedTextColor.GREEN));
                },
                20L);

        // --- Async delayed task ---
        // Good for database writes, file I/O, HTTP calls.
        // NEVER touch Bukkit world state (blocks, entities) inside async tasks.
        getServer().getAsyncScheduler().runDelayed(
                this,
                t -> getLogger().info("Async: logged join for " + player.getName()),
                1L, TimeUnit.SECONDS);

        // --- Global region delayed task ---
        // Runs on the server's global region thread — safe for non-world-specific actions.
        getServer().getGlobalRegionScheduler().runDelayed(
                this,
                t -> getLogger().info("Online count: " + getServer().getOnlinePlayers().size()),
                40L);
    }

    /**
     * Start a region-aware repeating task tied to a player's location.
     * Cancels itself when the player goes offline.
     * Returns the ScheduledTask so the caller can cancel early if needed.
     */
    private ScheduledTask startHeartbeat(Player player) {
        return getServer().getRegionScheduler().runAtFixedRate(
                this,
                player.getLocation(),
                t -> {
                    if (!player.isOnline()) {
                        t.cancel();
                        return;
                    }
                    player.sendMessage(Component.text("Heartbeat.", NamedTextColor.GRAY));
                },
                20L, // initial delay (ticks)
                20L  // period (ticks)
        );
    }
}
